test_basic_operation[
 from prefect import flow

 class ClassName: 
 @flow(name="My custom name")
 @staticmethod
 def flow_method(name: str) -> str:
 """
 My docstring

 Args:
 name (str): A name
 """
 return name
 -ClassName.flow_method]

test_dynamic_name[
 from prefect import flow

 def get_name():
 return "from-a-function"

 @flow(name=get_name())
 def flow_function(name: str) -> str:
 return name
 -flow_function-from-a-function]

