test_dynamic_name_depends_on_missing_import[
 from prefect import flow

 from non_existent import get_name

 class ClassName:
 @flow(name=get_name())
 @staticmethod
 def flow_method(name: str) -> str:
 return name
 -ClassName.flow_method]

test_annotations_and_defaults_rely_on_imports[
 import datetime
 from prefect import flow
 from prefect.types import DateTime
 from zoneinfo import ZoneInfo

 class ClassName: 
 @flow
 @staticmethod
 def flow_method(
 x: datetime.datetime,
 y: DateTime = DateTime(2025, 1, 1, tzinfo=ZoneInfo("UTC")),
 z: datetime.timedelta = datetime.timedelta(seconds=5),
 ):
 return x, y, z
 -ClassName.flow_method]

