test_defaults_rely_on_missing_import[
 from prefect import flow

 from non_existent import DEFAULT_NAME, DEFAULT_AGE

 class ClassName:
 @flow
 @staticmethod
 def flow_method(name = DEFAULT_NAME, age = DEFAULT_AGE) -> str:
 return name, age
 -ClassName.flow_method]

test_annotations_and_defaults_rely_on_imports[
 import datetime
 from prefect import flow
 from prefect.types import DateTime
 from zoneinfo import ZoneInfo

 class ClassName: 
 @flow
 @classmethod
 def flow_method(
 cls,
 x: datetime.datetime,
 y: DateTime = DateTime(2025, 1, 1, tzinfo=ZoneInfo("UTC")),
 z: datetime.timedelta = datetime.timedelta(seconds=5),
 ):
 return x, y, z
 -ClassName.flow_method]

test_function_with_enum_argument[
 from enum import Enum
 from prefect import flow

 class Color(Enum):
 RED = "RED"
 GREEN = "GREEN"
 BLUE = "BLUE"

 class ClassName:
 @flow
 @classmethod
 def flow_method(cls, x: Color = Color.RED):
 return x
 -ClassName.flow_method]

